    explanation: '建築基準法第20条・第36条及び施行令第129条の2の3により、建築物に設ける昇降機、避雷設備等の建築設備は、構造耐力上安全なものとして政令で定める技術的基準に適合させなければならない。令129条の2の4により、建築設備の配管設備は構造耐力上主要な部分を貫通して配管する場合に建築物の構造耐力上支障を生じないようにし、地震時の変位に追従できる措置を講じる。昇降機は令129条の3以下、避雷設備は法33条・令129条の14以下に技術的基準が定められている。\n\n【図解】建築設備の構造上の規定\n　設備｜要求される内容｜根拠\n　配管設備｜構造耐力上支障のない貫通・変位追従｜令129条の2の4\n　昇降機｜かご・昇降路・機械室の構造と安全装置｜令129条の3以下\n　避雷設備｜高さ20m超の建築物に設置｜法33条・令129条の14\n　⇒ 設備も構造耐力上安全であることが求められる\n　⚠ 設備機器は建築物本体と別扱いで構造検討不要とするのは誤り。',
