    correctKey: 'C',
    explanation: '消防法施行規則第28条の3により、誘導灯の種類は①避難口誘導灯（避難口の位置を示す）、②通路誘導灯（避難の方向を示す）、③客席誘導灯（客席内の通路を照らす）の3種類である。有効点灯時間は原則20分以上（高層建築物等は60分以上）とされている。避難口誘導灯は緑地に白のシンボル、通路誘導灯は白地に緑のシンボルで表示する。誘導灯にはA級・B級・C級の区分があり、表示面の縦寸法と有効範囲が定められている。客席誘導灯は客席内の通路の床面において0.2lx以上の照度を確保する。\n\n【図解】誘導灯の種類と要件\n　種類｜表示｜設置箇所\n　避難口誘導灯｜緑地に白のシンボル｜避難口・直通階段の出入口上部\n　通路誘導灯｜白地に緑のシンボル｜廊下の曲がり角・分岐部\n　客席誘導灯｜床面0.2lx以上｜劇場等の客席内通路\n　⇒ 非常電源は20分間以上、大規模防火対象物では60分間以上\n　⚠ 避難口（緑地）と通路（白地）の地色の取り違えが定番。',
