    correctKey: 'C',
    explanation: '消防法第17条の3の3および消防法施行規則第31条の6により、消防用設備等の点検は機器点検（6ヶ月に1回）と総合点検（1年に1回）が義務付けられている。点検結果の報告は特定防火対象物は1年に1回、非特定防火対象物は3年に1回、消防署長等に提出する。点検の実施は機器点検6か月ごと、総合点検1年ごとで、防火対象物の区分にかかわらず同じである。異なるのは報告の周期で、特定防火対象物は1年に1回、非特定防火対象物は3年に1回である。一定規模以上のものは消防設備士または消防設備点検資格者が点検を行う。\n\n【図解】消防用設備等の点検と報告\n　項目｜内容｜周期\n　機器点検｜外観と機能の確認｜6か月ごと（全対象物）\n　総合点検｜作動させて総合的に確認｜1年ごと（全対象物）\n　報告（特定防火対象物）｜消防長または消防署長へ｜1年に1回\n　報告（非特定防火対象物）｜同上｜3年に1回\n　⇒ 点検の周期は共通、報告の周期だけが用途で分かれる\n　⚠ 非特定は点検も3年に1回でよいとするのは誤り。',
