    explanation: '消防法施行令第24条により、非常警報設備（非常ベル、自動式サイレン、放送設備）の設置は防火対象物の種別・収容人員・規模によって義務付けられる。自動火災報知設備を設置した場合は非常警報設備の設置を免除される場合がある。非常警報設備には非常ベル、自動式サイレン、放送設備があり、収容人員50人以上の防火対象物などに設置する。自動火災報知設備または非常警報設備の有効範囲内では設置を省略できる場合がある。収容人員が800人以上または地階を除く階数11以上等では放送設備が必要となる。\n\n【図解】非常警報器具と非常警報設備\n　区分｜内容｜設置の目安\n　非常警報器具｜警鐘・携帯用拡声器・手動式サイレン｜収容人員20人以上等の小規模\n　非常警報設備｜非常ベル・自動式サイレン・放送設備｜収容人員50人以上等\n　放送設備の付加｜非常ベル等と併設｜収容人員800人以上や階数11以上等\n　⇒ 自動火災報知設備がある場合は省略できることがある\n　⚠ 非常警報設備と自動火災報知設備は別の設備。混同しないこと。',
