    correctKey: 'A',
    explanation: 'PAL*（Perimeter Annual Load Star）は、建築物のペリメーターゾーン（外壁から5m以内の範囲等）における年間熱負荷（MJ/年）をペリメーターゾーンの床面積（㎡）で除した値（MJ/㎡・年）で、値が小さいほど外皮性能が優れていることを示す。PAL*は外皮性能を評価する指標で、ペリメーターゾーンの年間熱負荷をその床面積で除して求める。値が小さいほど外皮の断熱・日射遮蔽性能が優れる。かつての省エネ法ではPAL、現行の建築物省エネ法ではPAL*が用いられ、モデル建物法でも外皮の評価に用いられる。\n\n【図解】非住宅建築物の性能指標\n　指標｜評価対象｜値の見方\n　PAL*｜ペリメーターゾーンの年間熱負荷｜小さいほど外皮性能が高い\n　BEI｜建築物全体の一次エネルギー消費量｜小さいほど省エネ性能が高い\n　ペリメーターゾーン｜外壁からおおむね5m以内等｜外皮の影響を受ける範囲\n　⇒ PAL*は外皮、BEIは設備を含む全体の指標\n　⚠ PAL*が大きいほど高性能とするのは誤り。小さいほど良い。',
