    correctKey: 'B',
    explanation: 'BEI（Building Energy Index）は設計一次エネルギー消費量を基準一次エネルギー消費量で除した値。省エネ基準への適合にはBEI≦1.0（非住宅建築物）が必要。ZEB Readyはβ≦0.5、Nearly ZEBはβ≦0.25（再エネ除き）、ZEBはβ≦0（再エネ含む）が目安。BEIは分子が設計一次エネルギー消費量、分母が基準一次エネルギー消費量で、その他一次エネルギー消費量は分子分母の双方から除いて算定する。値が小さいほど省エネ性能が高い。\n\n【図解】BEIとZEBの区分\n　BEIの値｜区分｜内容\n　1.0以下｜省エネ基準適合｜適合性判定の合格ライン\n　0.5以下｜ZEB Ready｜再エネを除いて50%削減\n　0.25以下｜Nearly ZEB｜再エネを含めて75%削減\n　0以下｜『ZEB』｜再エネを含めて100%削減\n　⇒ BEI＝設計一次エネ消費量÷基準一次エネ消費量\n　⚠ 分子と分母を逆にすると評価が正反対になる。',
