    explanation: '建築物省エネ法の住宅における外皮性能評価は、UA値（外皮平均熱貫流率）とηAC値（冷房期の平均日射熱取得率）を用いる。UA値は小さいほど断熱性能が高く、基準値は地域区分（1〜8地域）により異なる。UA値は外皮総熱損失量を外皮表面積で除した値で単位はW/(m²・K)、ηAC値は冷房期の日射の入りやすさを表す無次元の指標である。地域区分1・2の寒冷地ではUA値の基準が厳しく、地域区分8の蒸暑地域ではUA値の基準がなくηAC値のみが定められる。\n\n【図解】住宅の外皮性能指標\n　指標｜内容｜値の見方\n　UA値（外皮平均熱貫流率）｜外皮総熱損失量÷外皮表面積｜小さいほど高断熱\n　ηAC値（冷房期の平均日射熱取得率）｜日射の入りやすさ｜小さいほど日射遮蔽が良い\n　地域区分｜1（寒冷）から8（蒸暑）｜地域ごとに基準値が異なる\n　⇒ 寒冷地はUA値、蒸暑地はηAC値が重要になる\n　⚠ UA値が大きいほど断熱性能が高いとするのは誤り。',
