    explanation: '建設リサイクル法第21条第1項により、解体工事業を営もうとする者は、建設業法の許可（土木工事業・建築工事業・解体工事業のいずれか）を受けている場合を除き、都道府県知事の登録を受けなければならない。登録の有効期間は5年であり、更新が必要。解体工事業の登録の有効期間は5年で更新が必要であり、営業所ごとおよび工事現場ごとに技術管理者を選任しなければならない。建設業法の土木工事業・建築工事業・解体工事業の許可を受けている場合は登録が不要である。\n\n【図解】解体工事業の登録\n　項目｜内容｜備考\n　登録先｜工事を行う区域の都道府県知事｜区域ごとに必要\n　有効期間｜5年｜更新が必要\n　技術管理者｜営業所と工事現場に選任｜資格または実務経験\n　登録が不要な場合｜土木・建築・解体工事業の許可保有｜建設業法の許可\n　⇒ 無登録営業には罰則が科される\n　⚠ 建設業の許可があっても、他業種の許可では登録が免除されない。',
