      correctKey: 'C',
      explanation: '施行令第112条第11項の竪穴区画は、主要構造部を準耐火構造等とした建築物において、階段・エレベーター昇降路・吹き抜け等の竪穴部分を他の部分と区画するものである。区画の開口部には特定防火設備を設けることが必要であり、煙感知器と連動して自動閉鎖する防火設備等が用いられる。竪穴区画はすべての建築物に適用されるわけではなく、対象建築物の要件（準耐火構造以上・3階以上等）を満たす場合に要求される。\n\n【図解】竪穴区画の要点\n　項目｜内容｜備考\n　対象｜階段・EV昇降路・吹抜け・ダクトスペース等｜3階以上の階に居室がある場合等\n　区画の構造｜準耐火構造の床・壁｜令112条11項\n　開口部｜特定防火設備（遮煙性能付き）｜煙感知器連動閉鎖\n　⇒ 上下階への煙の伝播を防ぐことが目的\n　⚠ 一般の防火設備では不可。特定防火設備が必要である。',
