      question: '建築基準法施行令第123条第3項の特別避難階段の構造に関する記述として、正しいものはどれか。',
      choices: [
        { key: 'A', text: '特別避難階段に設ける付室には、排煙設備または機械排煙設備を設ける必要はない。', explanation: '誤り。施行令第123条第3項第2号の規定により、特別避難階段の付室（バルコニーを除く）には排煙設備を設けるか、または外気に向かって開くことができる窓を設けなければならない。付室への排煙対策は必須である。' },
        { key: 'B', text: '特別避難階段の階段室の壁は、準耐火構造以上であれば足りる。', explanation: '誤り。施行令第123条第3項第4号の規定により、特別避難階段の階段室・付室を区画する壁は耐火構造でなければならず、準耐火構造では要件を満たさない。' },
        { key: 'C', text: '特別避難階段の付室から階段室への出入口には、防火設備（旧乙種防火戸）を設ければ足りる。', explanation: '誤り。施行令第123条第3項第6号の規定により、特別避難階段の階段室・付室の出入口には特定防火設備（遮炎性能1時間）を設けなければならない。防火設備（旧乙種）では不足する。' },
        { key: 'D', text: '特別避難階段の付室の床面積は5m²以上としなければならない。', explanation: '正しい。施行令第123条第3項第3号の規定により、特別避難階段に設ける付室の床面積は、居室から廊下等を経て通じる場合は10m²以上、その他の場合は5m²以上としなければならない。' },
      ],
      correctKey: 'D',
      explanation: '施行令第123条第3項は特別避難階段の構造要件を詳細に規定している。付室の床面積は5m²以上（廊下経由の場合は10m²以上）が必要であり、階段室・付室を区画する壁は耐火構造、出入口は特定防火設備とし、付室には有効な排煙対策（排煙設備または外気開口）を講じなければならない。これらの要件は試験頻出事項である。\n\n【図解】特別避難階段の構造（令123条3項）\n　部分｜要求内容｜数値\n　付室（バルコニー）｜排煙設備または加圧防煙｜煙の侵入防止\n　付室の床面積｜屋内からバルコニー等を経由｜10m²以上（共同住宅は3m²以上）\n　区画｜階段室と付室を耐火構造の壁で区画｜開口部は特定防火設備\n　⇒ 15階以上または地下3階以下の階に通ずる階段に必要\n　⚠ 付室の面積要件は用途により異なる。数値の丸暗記に注意。',
      hasDiagram: false,
