      correctKey: 'C',
      explanation: '施行令第126条の2は排煙設備の設置義務を、令第126条の3は排煙設備の構造基準を規定している。機械排煙設備の排煙量については令第126条の3第1項第5号で防煙区画床面積1m²につき毎分1m³以上かつ毎分240m³以上（排煙機1台当たり）等の規定があり、単純な1m³/min/m²のみの基準ではない点が誤りとなる。排煙口の位置・面積要件についても正確な数値の把握が求められる。\n\n【図解】排煙設備の規定\n　項目｜内容｜根拠\n　設置義務｜特殊建築物500m²超、階数3以上で500m²超、無窓居室等｜令126条の2\n　防煙区画｜500m²以内ごと・防煙垂れ壁50cm以上｜令126条の3\n　排煙口の位置｜天井または天井から80cm以内の壁上部｜水平距離30m以下\n　⇒ 機械排煙は1m³/min/m²以上かつ120m³/min以上\n　⚠ 排煙口の80cmと防煙垂れ壁の50cmを取り違えないこと。',
