      choices: [
        { key: 'A', text: '耐火構造の壁の耐火時間は、建築物の用途や階数にかかわらず一律1時間とされている。', explanation: '誤り。施行令第107条の耐火性能の技術的基準は、構造部分の種類（柱・壁・床・梁等）及び当該部分が最上階から数えた階数等によって耐火時間が1時間・2時間等に区分されており、一律ではない。' },
        { key: 'B', text: '耐火構造の柱は、建築物のすべての階において常に2時間以上の耐火時間が必要とされる。', explanation: '誤り。施行令第107条第1号の規定では、柱の耐火時間は最上階から数えた階数によって異なり、最上階から2階以内の柱は1時間以上、3階から4階以内は1時間30分以上、5階以上は2時間以上とされている。' },
        { key: 'C', text: '耐火構造の床の耐火時間は、すべての床について2時間以上が必要とされる。', explanation: '誤り。施行令第107条第2号の規定では、床の耐火時間は最上階から数えた階数等によって区分されており、すべての床が一律に2時間以上であるわけではない。1時間以上で足りる場合もある。' },
        { key: 'D', text: '最上階から数えた階数が2以内の柱の耐火時間は、1時間以上でよい。', explanation: '正しい。施行令第107条第1号の規定により、最上階から数えた階数が2以内の柱に必要な耐火時間は1時間以上とされている。階数が増えるほど（3～4階以内は1.5時間、5階以上は2時間）必要な耐火時間が増大する。' },
      ],
      correctKey: 'D',
      explanation: '施行令第107条は耐火性能の技術的基準として、構造部分の種類と建築物の最上階から数えた階数に応じた耐火時間を定めている。柱については最上階から2階以内は1時間以上、3階から4階以内は1時間30分以上、5階以上は2時間以上が必要とされ、階数に応じて段階的に厳しくなる。壁・床・梁についても同様の考え方で耐火時間が規定されており、一律の時間が課されるわけではない。\n\n【図解】耐火性能の要求時間（令107条）\n　部位｜最上階から数えた階数2以内｜5以上\n　柱・はり｜1時間｜2時間\n　壁（耐力壁）・床｜1時間｜2時間\n　屋根・階段｜30分｜30分\n　⇒ 下階ほど支える荷重が大きく要求時間が長くなる\n　⚠ 屋根と階段は階数にかかわらず30分。柱と混同しないこと。',
