      explanation: '法第52条第9項・令第135条の18の特定道路特例では、加算できる容積率はWa＝（12-Wr）×（70-La）/70（Wr：前面道路幅員、La：特定道路からの距離）で算定される。前面道路幅員Wrが大きいほど加算容積率は小さくなり「一律」ではない。記述Dが誤り。特定道路（幅員15m以上）から70m以内にある幅員6m以上12m未満の前面道路に接する敷地が対象。\n\n【図解】特定道路による容積率の加算\n　項目｜内容｜備考\n　適用条件｜幅員15m以上の特定道路から70m以内｜前面道路の幅員6m以上12m未満\n　加算幅員Wa｜(12−Wr)×(70−La)÷70｜Wrは前面道路幅員、Laは特定道路からの距離\n　効果｜Wr＋Waを前面道路幅員とみなす｜容積率が緩和される\n　⇒ 特定道路から遠いほど、また前面道路が広いほど加算は小さい\n　⚠ 一律の加算値ではない。距離と幅員で変動する。',
