      correctKey: 'C',
      explanation: '消防法施行規則第18条の規定により、駐車場に設ける泡消火設備には固定式のほか移動式も認められている。したがって「移動式の設置が認められない」とする選択肢Cは誤りであり正答となる。泡消火設備は主に油火災（B火災）に対し有効な設備である。泡消火設備には固定式（全域放出方式・局所放出方式）と移動式があり、駐車場では車両の移動により泡が乱されることを考慮して方式を選ぶ。移動式は煙が著しく充満しない場所に限られる。\n\n【図解】泡消火設備の方式\n　方式｜内容｜適用場所\n　固定式（全域放出）｜区画全体に泡を放出｜駐車場・危険物施設\n　固定式（局所放出）｜対象物に直接放出｜屋外の危険物施設\n　移動式｜ホースとノズルを人が操作｜煙が著しく充満しない場所\n　⇒ 駐車場では移動式も認められている\n　⚠ 駐車場に移動式が一切認められないとするのは誤り。',
      hasDiagram: false,
      difficulty: 'basic',
