      correctKey: 'C',
      explanation: '不活性ガス消火設備の全域放出方式は、防護区画内の酸素濃度を消火に必要なレベルまで低下させるため、人が在室中に放出すると窒息の危険がある。消防法施行規則第19条において放出前の人員退避確認・警報等の措置が義務づけられており、選択肢Cは誤りで正答となる。全域放出方式では起動から放出まで20秒以上の遅延装置、放出前の音響警報、出入口の放出表示灯が必要で、常時人がいる場所には設置できない。放出後は排出装置で換気してから入室する。\n\n【図解】不活性ガス消火設備の安全対策\n　対策｜内容｜目的\n　遅延装置｜起動から放出まで20秒以上｜退避時間の確保\n　音響警報装置｜放出前に警報｜在室者への周知\n　放出表示灯｜出入口に設置｜再進入の防止\n　⇒ 常時人のいる場所への全域放出方式は認められない\n　⚠ 二酸化炭素は高濃度で致死的。放出後の入室には濃度確認が必須。',
