      explanation: '消防法施行令第7条の規定により、消防用設備等は「消防の用に供する設備」（消火設備・警報設備・避難設備）、「消防用水」（防火水槽・ため池・プール等）、「消火活動上必要な施設」（排煙設備・連結送水管・非常コンセント設備等）の3種類に大別される。防火水槽は消防用水に分類されるため、本問の正解は選択肢Bである。\n\n【図解】消防用設備等の3分類（令7条）\n　分類｜内訳｜例\n　消防の用に供する設備｜消火設備・警報設備・避難設備｜消火器・自火報・誘導灯\n　消防用水｜防火水槽・ため池・プール等｜大規模防火対象物に設置\n　消火活動上必要な施設｜排煙・連結散水・連結送水管・非常コンセント・無線通信補助｜消防隊が使用\n　⇒ 誰が使うかで分類が分かれる\n　⚠ 連結送水管を消火設備に分類するのは誤り。消火活動上必要な施設。',
