      subjectName: '建築法規',
      category: '省エネ法・その他法令',
      question: '高齢者、障害者等の移動等の円滑化の促進に関する法律（バリアフリー法）第2条に規定される用語の定義に関する記述として、最も不適当なものはどれか。',
      choices: [
        { key: 'A', text: '「特定建築物」とは、学校、病院、劇場、観覧場、集会場、展示場、百貨店、ホテル、事務所、共同住宅、老人ホームその他の多数の者が利用する建築物であって政令で定めるものをいう。', explanation: 'バリアフリー法第2条第18号の規定通りであり、多数の者が利用する建築物として政令で定めるものが特定建築物とされている。適当な記述である。' },
        { key: 'B', text: '「特別特定建築物」とは、特定建築物のうち、不特定かつ多数の者が利用し、または主として高齢者、障害者等が利用する建築物であって政令で定めるものをいう。', explanation: 'バリアフリー法第2条第19号の規定通りであり、不特定多数または高齢者・障害者等が主として利用する建築物が特別特定建築物として規定されている。適当な記述である。' },
        { key: 'C', text: '「建築物移動等円滑化基準」とは、移動等円滑化のために必要な建築物特定施設の構造および配置に関する基準であって、政令で定めるものをいう。', explanation: 'バリアフリー法第2条第20号の規定通りであり、建築物移動等円滑化基準（義務基準）は政令で定められている。適当な記述である。' },
        { key: 'D', text: '「高齢者、障害者等」とは、60歳以上の者と身体障害者手帳の交付を受けた者のみを指すものとして法律に定義されている。', explanation: 'バリアフリー法第2条第1号の定義はより広く、高齢者のほか、障害者基本法に規定する障害者（身体・知的・精神等）を含むものとされており、60歳以上・身体障害者のみという限定は不適当である。' },
      ],
      correctKey: 'D',
      explanation: 'バリアフリー法第2条第1号は「高齢者、障害者等」を広く定義しており、身体障害者手帳の交付を受けた者のみに限定されない。知的障害者、精神障害者、発達障害者等も含まれ、また高齢者の年齢要件も法律上明記されていないため、選択肢Dが不適当である。バリアフリー法の対象には高齢者、身体障害者、知的障害者、精神障害者、発達障害者、妊産婦、けが人など日常生活や社会生活に身体の機能上の制限を受ける者が広く含まれる。\n\n【図解】バリアフリー法の主な用語\n　用語｜内容｜備考\n　高齢者、障害者等｜身体の機能上の制限を受ける者｜手帳の有無を問わない\n　特定建築物｜多数の者が利用する建築物｜努力義務\n　特別特定建築物｜不特定多数または高齢者等が主に利用｜適合義務\n　⇒ 対象者を手帳所持者に限定していない点が重要\n　⚠ 身体障害者手帳の交付を受けた者に限るとするのは誤り。',
