      explanation: 'バリアフリー法第17条に基づく認定特定建築物の認定制度では、特定建築物であれば床面積の下限に関する特別な規定はなく、5,000㎡以上という要件は法令に存在しない。誘導基準への適合計画を申請することができる特定建築物であれば認定を受けることができ、選択肢Dが不適当である。認定特定建築物は誘導基準に適合する計画について所管行政庁の認定を受けたもので、認定を受けると容積率の特例や表示（認定マーク）の使用、支援措置の対象となる。\n\n【図解】認定特定建築物の制度\n　項目｜内容｜備考\n　認定の対象｜特定建築物の建築等の計画｜床面積の下限規定はない\n　認定の基準｜建築物移動等円滑化誘導基準への適合｜義務基準より高い水準\n　効果｜容積率特例・認定表示・支援措置｜法17条から19条\n　⇒ 認定は任意の申請に基づく制度\n　⚠ 5,000m²以上という面積要件は法令に存在しない。',
