      correctKey: 'C',
      explanation: '建設リサイクル法施行令第2条第1号は解体工事の対象規模を「当該工事により解体される建築物等の床面積の合計80㎡以上」と規定しており、同一工事現場における複数の建築物の床面積を合算して判定することは認められている。「合算不可」とする選択肢Cが不適当である。解体工事は80m²以上、新築・増築は500m²以上、修繕・模様替は請負代金1億円以上、建築物以外の工作物は請負代金500万円以上が対象建設工事の規模基準である。\n\n【図解】対象建設工事の規模基準\n　工事の種類｜規模基準｜備考\n　建築物の解体工事｜床面積80m²以上｜同一現場の合計で判断\n　建築物の新築・増築｜床面積500m²以上｜用途を問わない\n　建築物の修繕・模様替｜請負代金1億円以上｜税込\n　建築物以外の工作物｜請負代金500万円以上｜土木工事等\n　⇒ 工事の種類ごとに基準の単位（面積と金額）が異なる\n　⚠ 80m²と500m²の取り違えが定番のひっかけ。',
