      explanation: '労働安全衛生法第17条では、安全委員会の設置義務が生じる事業場規模は業種によって異なる。建設業・製造業等は常時50人以上だが、その他の業種では100人以上と規定されており、すべての業種で50人以上とする記述は誤りである。設置義務の有無は業種区分によって判断する必要がある。事業場の規模に応じて総括安全衛生管理者、安全管理者、衛生管理者、産業医の選任と、安全委員会・衛生委員会の設置が義務づけられる。建設現場では混在作業に対応した統括安全衛生責任者の制度もある。\n\n【図解】安全衛生管理体制\n　選任・設置｜規模の目安｜備考\n　総括安全衛生管理者｜建設業は常時100人以上｜業種により異なる\n　安全委員会｜建設業・製造業等は常時50人以上｜その他の業種は100人以上\n　衛生委員会｜業種を問わず常時50人以上｜安全衛生委員会として一体運営も可\n　⇒ 業種によって人数要件が異なる点が要点\n　⚠ 安全委員会の設置基準を全業種50人以上とするのは誤り。',
